export const environment = {
  production: false,
  // A porta correta da API é 3001 (a que roda de fato o api.js do desafio).
  // O PDF do desafio cita 3000, mas o back-end entregue já está configurado para rodar em 3001.
  apiUrl: 'http://localhost:3001'
};
